// can we split books into ≤ k students, each ≤ cap pages?
bool feasible(vector<ll>& pages, int k, ll cap) {
    int students = 1; ll cur = 0;
    for (ll p : pages) {
        if (p > cap) return false;          // single book exceeds
        if (cur + p > cap) { students++; cur = p; }
        else cur += p;
    }
    return students <= k;
}
