// students needed if no one may read more than 'cap' pages
int studentsNeeded(const vector<int>& books, int cap) {
    int students = 1, load = 0;
    for (int b : books) {
        if (load + b > cap) { ++students; load = b; }   // start a new student
        else                  load += b;
    }
    return students;
}

int allocateMinimumPages(const vector<int>& books, int m) {
    if ((int)books.size() < m) return -1;              // cannot give everyone a book
    int lo = *max_element(books.begin(), books.end()); // no cap below the biggest book
    int hi = accumulate(books.begin(), books.end(), 0);
    int ans = hi;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (studentsNeeded(books, mid) <= m) { ans = mid; hi = mid - 1; }  // feasible
        else                                   lo = mid + 1;
    }
    return ans;
}

