def students_needed(books: list[int], cap: int) -> int:
    """Students needed if no one may read more than cap pages."""
    students, load = 1, 0
    for b in books:
        if load + b > cap:
            students += 1        # start a new student
            load = b
        else:
            load += b
    return students


def allocate_minimum_pages(books: list[int], m: int) -> int:
    if len(books) < m:
        return -1                          # cannot give everyone a book
    lo, hi = max(books), sum(books)         # no cap below the biggest single book
    ans = hi
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if students_needed(books, mid) <= m:   # feasible
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

