// cows placeable if consecutive cows must be at least 'd' apart
int cowsPlaced(const vector<int>& stalls, int d) {
    int count = 1, last = stalls[0];
    for (size_t i = 1; i < stalls.size(); ++i)
        if (stalls[i] - last >= d) { ++count; last = stalls[i]; }
    return count;
}

int aggressiveCows(vector<int> stalls, int cows) {
    sort(stalls.begin(), stalls.end());
    int lo = 1, hi = stalls.back() - stalls.front(), ans = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (cowsPlaced(stalls, mid) >= cows) { ans = mid; lo = mid + 1; }  // feasible: try wider
        else                                   hi = mid - 1;
    }
    return ans;
}

