def cows_placed(stalls: list[int], d: int) -> int:
    """Cows placeable if consecutive cows must be at least d apart."""
    count, last = 1, stalls[0]
    for x in stalls[1:]:
        if x - last >= d:
            count += 1
            last = x
    return count


def aggressive_cows(stalls: list[int], cows: int) -> int:
    stalls = sorted(stalls)
    lo, hi, ans = 1, stalls[-1] - stalls[0], 0
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if cows_placed(stalls, mid) >= cows:   # feasible: try wider
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

