long long hoursAt(const vector<int>& piles, int speed) {
    long long h = 0;
    for (int p : piles) h += (p + speed - 1) / speed;   // ceil division
    return h;
}

int minEatingSpeed(const vector<int>& piles, int h) {
    int lo = 1, hi = *max_element(piles.begin(), piles.end()), ans = hi;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (hoursAt(piles, mid) <= h) { ans = mid; hi = mid - 1; }   // fast enough
        else                            lo = mid + 1;
    }
    return ans;
}

