def hours_at(piles: list[int], speed: int) -> int:
    return sum((p + speed - 1) // speed for p in piles)   # ceil division


def min_eating_speed(piles: list[int], h: int) -> int:
    lo, hi = 1, max(piles)
    ans = hi
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if hours_at(piles, mid) <= h:      # fast enough
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

