int daysNeeded(const vector<int>& w, int cap) {
    int days = 1, load = 0;
    for (int x : w) {
        if (load + x > cap) { ++days; load = x; }   // ship today, start tomorrow
        else                  load += x;
    }
    return days;
}

int shipWithinDays(const vector<int>& w, int D) {
    int lo = *max_element(w.begin(), w.end());      // must fit the heaviest package
    int hi = accumulate(w.begin(), w.end(), 0), ans = hi;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (daysNeeded(w, mid) <= D) { ans = mid; hi = mid - 1; }
        else                           lo = mid + 1;
    }
    return ans;
}

