long long woodAt(const vector<int>& trees, long long H) {
    long long total = 0;
    for (int t : trees) if (t > H) total += t - H;
    return total;
}

long long maxSawHeight(const vector<int>& trees, long long M) {
    long long lo = 0, hi = *max_element(trees.begin(), trees.end()), ans = 0;
    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;
        if (woodAt(trees, mid) >= M) { ans = mid; lo = mid + 1; }   // still enough: go higher
        else                           hi = mid - 1;
    }
    return ans;
}

