def wood_at(trees: list[int], H: int) -> int:
    return sum(t - H for t in trees if t > H)


def max_saw_height(trees: list[int], M: int) -> int:
    lo, hi, ans = 0, max(trees), 0
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if wood_at(trees, mid) >= M:      # still enough: raise the blade
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

