double findMedianSortedArrays(vector<int>& A, vector<int>& B) {
    if (A.size() > B.size()) return findMedianSortedArrays(B, A);   // search the shorter
    int m = (int)A.size(), n = (int)B.size();
    int lo = 0, hi = m;                       // cut position in A: 0..m
    while (lo <= hi) {
        int i = lo + (hi - lo) / 2;           // take i from A
        int j = (m + n + 1) / 2 - i;          // ...so total left half is fixed
        // sentinels remove every empty-side special case
        long long Aleft  = (i == 0) ? LLONG_MIN : A[i - 1];
        long long Aright = (i == m) ? LLONG_MAX : A[i];
        long long Bleft  = (j == 0) ? LLONG_MIN : B[j - 1];
        long long Bright = (j == n) ? LLONG_MAX : B[j];

        if (Aleft <= Bright && Bleft <= Aright) {          // correct cut
            if ((m + n) % 2) return (double)max(Aleft, Bleft);   // odd: left max
            return (max(Aleft, Bleft) + min(Aright, Bright)) / 2.0;
        }
        if (Aleft > Bright) hi = i - 1;       // took too many from A
        else                lo = i + 1;       // took too few
    }
    return 0.0;
}
